def tool(data, params):
    code = params['series']
    start = int(params.get('start_year', 2015))
    end = int(params.get('end_year', 2022))
    s = data[code]
    regions = data['regions']
    names = data['names']
    counts = {}
    for y in range(start, end + 1):
        counts[y] = 0
    latest = {}
    for unit in s:
        if unit not in regions:
            continue
        obs = s[unit]
        for y in obs:
            yy = int(y)
            v = obs[y]
            if v is None or yy < start or yy > end:
                continue
            counts[yy] += 1
            if unit not in latest or yy > latest[unit]:
                latest[unit] = yy
    facts = {}
    for y in range(start, end + 1):
        facts['countries_' + str(y)] = counts[y]
    total = len(latest)
    facts['countries_with_any_estimate'] = total
    facts['countries_in_scope'] = len(regions)
    if total > 0:
        yrs = [latest[u] for u in latest]
        facts['median_latest_year'] = statistics.median(yrs)
        facts['oldest_latest_year'] = min(yrs)
        facts['newest_latest_year'] = max(yrs)
        peak = max(range(start, end + 1), key=lambda y: counts[y])
        facts['peak_year'] = peak
        facts['coverage_share_pct'] = round(100.0 * total / max(1, len(regions)), 1)
    else:
        facts['note'] = 'no observations in window'
    summary = 'Series ' + code + ': ' + str(total) + ' of ' + str(len(regions)) + ' countries have at least one observation between ' + str(start) + ' and ' + str(end) + '. Counts per year are given as facts; countries without an observation are missing, not zero.'
    return {'facts': facts, 'summary': summary}

