def tool(data, params):
    code = params['series']
    cutoff = params['cutoff_year']
    regions = data['regions']
    names = data['names']
    series = data[code]
    by_region = {}
    total_with = 0
    total_recent = 0
    total_countries = 0
    for unit in series:
        for c in series[unit]:
            pass
    units = list(series.keys())
    merged = {}
    for unit in units:
        for c in series[unit]:
            merged[c] = series[unit][c]
    for c in merged:
        if c not in regions:
            continue
        obs = merged[c]
        years = [int(y) for y in obs if obs[y] is not None]
        if len(years) == 0:
            continue
        r = regions[c]
        if r not in by_region:
            by_region[r] = {'with_data': 0, 'recent': 0}
        by_region[r]['with_data'] += 1
        total_with += 1
        if max(years) >= cutoff:
            by_region[r]['recent'] += 1
            total_recent += 1
    facts = {'countries_with_any_estimate': total_with, 'countries_with_estimate_at_or_after_cutoff': total_recent, 'cutoff_year': cutoff}
    if total_with > 0:
        facts['share_recent_percent'] = round(100.0 * total_recent / total_with, 1)
    parts = []
    for r in sorted(by_region):
        facts['recent_' + r] = by_region[r]['recent']
        facts['with_data_' + r] = by_region[r]['with_data']
        parts.append(r + ': ' + str(by_region[r]['recent']) + ' of ' + str(by_region[r]['with_data']))
    summary = 'Of ' + str(total_with) + ' countries with any value for ' + code + ', ' + str(total_recent) + ' have a value dated ' + str(cutoff) + ' or later. By region: ' + '; '.join(parts) + '. Countries without any value are not counted; whether a dated value is survey-based or modelled is not stated by the series itself.'
    return {'facts': facts, 'summary': summary}

