def tool(data, params):
    code = params['series']
    y0 = int(params['base_year'])
    s = data.get(code, {})
    regions = data['regions']
    names = data['names']
    out = {}
    units = list(s.keys())
    if len(units) == 0:
        return {'facts': {'series_present': 'no'}, 'summary': 'The series ' + str(code) + ' returned no data; the legacy 1.25 dollar line cannot be read from it and the series may be discontinued.'}
    unit = units[0]
    d = s[unit]
    latest_by = {}
    base_by = {}
    for c in d:
        if c not in regions:
            continue
        ys = [int(y) for y in d[c] if d[c][y] is not None] if isinstance(d[c], dict) else []
        if len(ys) == 0:
            continue
    # data layout: unit -> year -> value, so iterate by year
    years = sorted([int(y) for y in d.keys()])
    out['unit'] = unit
    if len(years) == 0:
        out['years_available'] = 0
        return {'facts': out, 'summary': 'The series ' + str(code) + ' has no observations in unit ' + str(unit) + '.'}
    latest = years[-1]
    def vals(y):
        yy = d.get(y, d.get(str(y), {}))
        return yy
    v_latest = vals(latest)
    v_base = vals(y0)
    out['first_year'] = years[0]
    out['latest_year'] = latest
    out['base_year'] = y0
    out['countries_latest'] = len([k for k in v_latest if k in regions and v_latest[k] is not None])
    out['countries_base'] = len([k for k in v_base if k in regions and v_base[k] is not None])
    lv = [v_latest[k] for k in v_latest if k in regions and v_latest[k] is not None]
    if len(lv) > 0:
        out['median_latest'] = round(statistics.median(lv), 2)
        out['max_latest'] = round(max(lv), 2)
    bv = [v_base[k] for k in v_base if k in regions and v_base[k] is not None]
    if len(bv) > 0:
        out['median_base'] = round(statistics.median(bv), 2)
    summary = 'Series ' + str(code) + ' (' + str(unit) + ') covers ' + str(years[0]) + ' to ' + str(latest) + '; ' + str(out['countries_base']) + ' countries report in ' + str(y0) + ' and ' + str(out['countries_latest']) + ' in ' + str(latest) + '. The series does not report the 1.25 dollar line; the legacy 1.25 series is discontinued, so the target is read against the line this series uses.'
    return {'facts': out, 'summary': summary}

