def tool(data, params):
    code = params['series']
    y0 = int(params['start_year'])
    y1 = int(params['end_year'])
    s = data[code]
    regions = data['regions']
    names = data['names']
    out = {}
    for unit in s:
        for c in s[unit]:
            if c not in regions:
                continue
            yrs = [int(y) for y in s[unit][c] if y0 <= int(y) <= y1]
            if not yrs:
                continue
            y = max(yrs)
            v = s[unit][c].get(y)
            if v is None:
                v = s[unit][c].get(str(y))
            if v is not None:
                out[c] = (y, v)
    n_all = len(regions)
    vals = [out[c][1] for c in out]
    facts = {'countries_with_data': len(vals), 'countries_total': n_all, 'coverage_share_pct': round(100.0 * len(vals) / n_all, 1) if n_all else 0}
    if vals:
        facts['median'] = round(statistics.median(vals), 2)
        facts['mean'] = round(statistics.mean(vals), 2)
        facts['min'] = round(min(vals), 2)
        facts['max'] = round(max(vals), 2)
        lo = min(out, key=lambda c: out[c][1])
        hi = max(out, key=lambda c: out[c][1])
        facts['lowest_country'] = names.get(lo, lo)
        facts['lowest_year'] = out[lo][0]
        facts['highest_country'] = names.get(hi, hi)
        facts['highest_year'] = out[hi][0]
        reg = {}
        for c in out:
            reg.setdefault(regions[c], []).append(out[c][1])
        for r in reg:
            facts['median_region_' + str(r)] = round(statistics.median(reg[r]), 2)
        summary = 'Series ' + code + ' has a latest value between ' + str(y0) + ' and ' + str(y1) + ' for ' + str(len(vals)) + ' of ' + str(n_all) + ' countries; the median is ' + str(facts['median']) + '. The series is national, not split by wealth quintile, so it cannot measure the poor directly. Latest years differ between countries.'
    else:
        summary = 'No country has data for ' + code + ' between ' + str(y0) + ' and ' + str(y1) + '.'
    return {'facts': facts, 'summary': summary}

