    names = data['names']
    notes = []
    units = list(s.keys())
    if not units:
        return {'facts': {'series_present': 0}, 'summary': 'Series ' + str(code) + ' returned no data; the 1.25 dollar line cannot be assessed and the series may be discontinued.'}
    unit = units[0]
    d = s[unit]
    def pick(year):
        vals = []
        for c in d:
            if c in regions:
                v = d[c].get(year) if isinstance(d[c], dict) else None
                if v is not None:
                    vals.append(v)
        return vals
    ycount = {}
    for c in d:
        if c in regions and isinstance(d[c], dict):
            for y in d[c]:
                if d[c][y] is not None:
                    ycount[y] = ycount.get(y, 0) + 1
    years = sorted(ycount.keys())
    if not years:
        return {'facts': {'series_present': 1, 'countries_with_data': 0}, 'summary': 'Series ' + str(code) + ' holds no country values; the target cannot be read from it.'}
    latest = years[-1]
    base = pick(y0)
    last = pick(latest)
    facts = {'unit': unit, 'base_year': y0, 'latest_year': latest, 'countries_base': len(base), 'countries_latest': len(last)}
    if last:
        facts['median_latest'] = round(statistics.median(last), 2)
        facts['mean_latest'] = round(statistics.mean(last), 2)
    if base:
        facts['median_base'] = round(statistics.median(base), 2)
    summary = 'Series ' + str(code) + ' (' + str(unit) + '): '
    summary += str(len(last)) + ' countries report in ' + str(latest) + '; '
    if last:
        summary += 'median ' + str(facts['median_latest']) + '. '
    if not base:
        summary += 'No country reports for ' + str(y0) + '; data are missing for the base year. '
    summary += 'The series is not the legacy 1.25 dollar line, which is discontinued, so the target needs reading against the line this series uses.'
    return {'facts': facts, 'summary': summary}

