    summary = 'Across ' + str(len(vals)) + ' countries, latest coverage of all social protection and labour programmes among the poorest quintile in ' + str(year_from) + '-' + str(year_to) + ' has a median of ' + str(facts['median']) + ' % of the quintile population, ranging from ' + str(facts['min']) + ' to ' + str(facts['max']) + '. Survey years differ between countries, so values are not strictly comparable.'
    return {'facts': facts, 'summary': summary}

